	// instance it is chosen again, and the rejected replacement never changed
	// the address to h2:9090.
	if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" {
		t.Fatalf("result 7: %+v", r)
	}
