2686			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":7,"healthy":true},
2687			{"type":"register","service":"svc","expectedRevision":9,"instances":[
2688				{"id":"i1","address":"api.exa mple:8080"},
2689				{"id":"i2","address":"db.example:9090"}
2690			]},
2691			{"type":"register","service":"svc","expectedRevision":1,"instances":[
2692				{"id":"i1","address":"api.example:8081"},
2693				{"id":"i2","address":"db.exa\u0001mple:9090"}
2694			]},
2695			{"type":"select","service":"svc","expectedRevision":1},
2696			{"type":"register","service":"svc","expectedRevision":1,"instances":[
2697				{"id":"i3","address":"cache.example:6379"}
2698			]}
2699		]}`
2700		out, code := runRegisterWith(t, input)
2701		if code != 1 {
2702			t.Fatalf("the two invalid items make the batch fail, exit code: %d, output: %s", code, out)
2703		}
2704		var got registerOutput
2705		if err := json.Unmarshal([]byte(out), &got); err != nil {
2706			t.Fatalf("output is not JSON: %v\n%s", err, out)
2707		}
2708		if len(got.Results) != 6 {
2709			t.Fatalf("results: %+v", got.Results)
2710		}
