2712		// expectedRevision 9 also mismatches: invalid wins, the reason names the
2713		// address problem, and the stamped revision is the current one (1). An
2714		// invalid result carries neither the conflict's revision pair nor target
2715		// instance fields.
2716		if r := got.Results[2]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
2717			r.ExpectedRevision != 0 || r.ActualRevision != 0 ||
2718			r.InstanceID != "" || r.Address != "" {
2719			t.Fatalf("whitespace address with a wrong revision must be invalid at revision 1: %+v", r)
2720		}
