2725		// valid change to i1 sitting earlier in the same list must not leak through.
2726		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
2727			r.ExpectedRevision != 0 || r.ActualRevision != 0 ||
2728			r.InstanceID != "" || r.Address != "" {
