2989				if err := json.Unmarshal([]byte(out), &got); err != nil {
2990					t.Fatalf("output is not JSON: %v\n%s", err, out)
2991				}
2992				if len(got.Results) != 1 || got.Results[0].OK || got.Results[0].Error != "invalid" {
