2994				}
2995				if !strings.Contains(got.Results[0].Reason, "sessionKey") &&
2996					!strings.Contains(got.Results[0].Reason, "service name") {
2997					t.Fatalf("reason should name sessionKey or the service field, got %q", got.Results[0].Reason)
2998				}
2999			})
3000		}
