3002		// A batch covering ordering and preservation of the binding.
3003		input := `{"requests":[
3004			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
3005			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
3006			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
3007			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"k"},
3008			{"type":"release_session","service":"svc","expectedRevision":9,"sessionKey":"  "},
3009			{"type":"release_session","service":"svc","expectedRevision":9,"sessionKey":"k"},
