// sessionRequestInput is the decoded content shared by select and
// release_session requests: the trimmed service name, the still-raw
// expectedRevision token, and the optional session key (nil when the field was
// omitted). Explicit null and non-string keys are rejected while decoding.
type sessionRequestInput struct {
	service    string
	revision   json.RawMessage
	sessionKey *string
}

// readSessionRequest decodes one select/release_session item, centralizing the
// input handling the two request kinds repeat. shapeReason wraps a malformed
// object error with the operation-specific wording. keyRequired distinguishes
// the two business contracts only for an absent key: select treats an omitted
// sessionKey as an ordinary rotating selection, while release_session rejects
// it as invalid naming the sessionKey problem.
//
// An explicitly provided null or a non-string key is invalid for both kinds,
// so it is rejected here before the revision token is parsed; the field order
// otherwise matches every other request kind: object shape, then the
// required-revision check and integer parsing, then the blank-key content
// check inside the registry's shared validator. On failure the item's invalid
// result is appended and ok is false; on success the caller applies the
// validated request and maps its own business outcome.
func (p *registerProcessor) readSessionRequest(raw json.RawMessage, service string, shapeReason, keyRequired bool) (sessionRequestInput, bool) {
	var req struct {
		Service  string          `json:"service"`
		Revision json.RawMessage `json:"expectedRevision"`
		Session  json.RawMessage `json:"sessionKey"`
	}
	if err := json.Unmarshal(raw, &req); err != nil {
		p.invalidf(service, shapeReason, err)
		return sessionRequestInput{}, false
	}
	service = strings.TrimSpace(req.Service)

	// sessionKey is optional on a select (absent means an ordinary rotating
	// selection) and mandatory on release_session. An explicitly provided null
	// or a non-string value is invalid for either kind — it names a sessionKey
	// type problem, never "no key submitted" — and is judged at the token
	// level before the revision token is parsed, matching the long-standing
	// field order. A present string reaches the registry untrimmed; the shared
	// validator trims it, so keys equal after trimming name one session and a
	// blank-after-trim key is rejected there after the revision is validated.
	var sessionKey *string
	if len(req.Session) > 0 {
		if strings.TrimSpace(string(req.Session)) == "null" {
			p.invalid(service, "sessionKey must be a string, not null")
			return sessionRequestInput{}, false
		}
		var key string
		if err := json.Unmarshal(req.Session, &key); err != nil {
			p.invalid(service, "sessionKey must be a string")
			return sessionRequestInput{}, false
		}
		sessionKey = &key
	} else if keyRequired {
		p.invalid(service, "sessionKey is required and must be a non-empty string")
		return sessionRequestInput{}, false
	}

	revision, ok := p.parseRevision(service, req.Revision)
	if !ok {
		return sessionRequestInput{}, false
	}
	return sessionRequestInput{service: service, revision: req.Revision, sessionKey: sessionKey}, true
}

